return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-10-01T20:49:59+00:00','po-revision-date'=>'2026-10-01T20:49:59+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Přesune knihovnu médií tohoto webu do objektového úložiště Zinn® a poskytuje ji prostřednictvím sítě CDN. Konfiguruje se z Vaší nástěnky Zinn® — do WordPressu se nikdy nezadává žádný přístupový klíč.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Uloženo. Chcete-li hodnotu nahradit, zadejte novou.','Filter this list…'=>'Filtrovat tento seznam…','Filter this list'=>'Filtrovat tento seznam','Nothing matches that filter.'=>'Tomuto filtru nic neodpovídá.','Add a row'=>'Přidat řádek','Remove this row'=>'Odebrat tento řádek','Remove'=>'Odebrat','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — přehled','Overview'=>'Přehled','Copied'=>'Zkopírováno','Every Zinn® plugin on this site, and whether it is working.'=>'Každý plugin Zinn® na tomto webu a zda funguje.','No connection is needed for this plugin.'=>'Pro tento plugin není vyžadováno žádné připojení.','Open settings'=>'Otevřít nastavení','You do not have permission to change these settings.'=>'Nemáte oprávnění ke změně těchto nastavení.','Settings sections'=>'Sekce nastavení','Support'=>'Podpora','Save changes'=>'Uložit změny','Tools'=>'Nástroje','Export settings'=>'Exportovat nastavení','Reset to defaults'=>'Obnovit výchozí','This puts every setting on this plugin back to its default. Continue?'=>'Tímto se všechna nastavení tohoto pluginu vrátí na výchozí hodnoty. Chcete pokračovat?','Diagnostics for support'=>'Diagnostika pro podporu','Import a settings file'=>'Importovat soubor s nastavením','Import'=>'Importovat','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Exportované soubory nikdy neobsahují hesla, tokeny ani klíče API — na novém webu je budete muset zadat znovu.','Settings saved.'=>'Nastavení bylo uloženo.','Every setting on this plugin is back to its default.'=>'Všechna nastavení tohoto pluginu byla obnovena do výchozího stavu.','Done.'=>'Hotovo.','That action is not available.'=>'Tato akce není k dispozici.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tento soubor se nepodařilo přečíst. Zvolte soubor s nastavením exportovaný z pluginu Zinn®.','That file is too large to be a settings export.'=>'Tento soubor je příliš velký na to, aby byl exportem nastavení.','That file is not a Zinn® settings export.'=>'Tento soubor není exportem nastavení Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Tento soubor byl exportován z jiného pluginu (%s), takže jeho importem zde by se uložila nastavení, kterým tento plugin nerozumí.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, proto je prosím zadejte znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, zadejte je proto znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, zadejte je proto znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, zadejte je proto znovu.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Služba Zinn Digital® nevrátila token. Na tomto webu nebylo nic změněno.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Tento web již není připojen k přesunu médií do Zinn®. Nová nahraná média zůstanou na tomto serveru. Spárujte jej znovu z Vaší nástěnky Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® odpověděl s HTTP %d.','Disconnected by Zinn Digital®.'=>'Odpojeno službou Zinn Digital®.','Connected'=>'Připojeno','Connecting…'=>'Připojování…','Connected, but something needs attention'=>'Připojeno, ale něco vyžaduje pozornost','Not connected'=>'Nepřipojeno','Running on your own account'=>'Běží na vašem vlastním účtu','We could not check this'=>'Toto se nám nepodařilo zkontrolovat','This plugin did not say why. Send a diagnostics report and we will look.'=>'Tento plugin neuvedl důvod. Pošlete zprávu o diagnostice a my se na to podíváme.','Connection status'=>'Stav připojení','Last checked %s ago.'=>'Naposledy zkontrolováno před %s.','(opens in a new tab)'=>'(otevře se v novém panelu)','Send this to Zinn® support'=>'Odešlete toto podpoře Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Přesně toto bude odesláno — nic jiného a nic skrytého. Vaše hesla, tokeny a klíče API v tom nejsou.','The diagnostics report that will be sent'=>'Diagnostická zpráva, která bude odeslána','Copy to clipboard'=>'Zkopírovat do schránky','Send this report to Zinn® support'=>'Odešlete toto hlášení podpoře Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otevřeme pro Vás požadavek na podporu a odpovíme e-mailem. Pokud jej nechcete odesílat, zkopírujte jej výše a vložte do požadavku sami.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Z tohoto serveru (%s) se nepodařilo kontaktovat Zinn Digital®. Zkopírujte výše uvedené hlášení a místo toho otevřete požadavek — ve vašem nastavení není žádná chyba.','Sent. Zinn® support has your report and will reply by email.'=>'Odesláno. Podpora Zinn® obdržela vaše hlášení a odpoví vám e-mailem.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Odesláno. Podpora Zinn® obdržela Vaše hlášení — reference %s — a odpoví Vám e-mailem.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Během krátké doby jste odeslali několik hlášení. Počkejte několik minut a zkuste to znovu — ta předchozí dorazila.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Službě Zinn Digital® se právě nepodařilo zprávu přijmout — chyba je na naší straně, ne na Vaší. Zkuste to prosím za chvíli znovu nebo zkopírujte výše uvedenou zprávu do požadavku.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Hlášení bylo odmítnuto (HTTP %d). Zkopírujte jej výše a otevřete požadavek na podporu s uvedením tohoto čísla.','%s — guides and services'=>'%s — návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku k %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Hosting Zinn® pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zavedené weby, domény a umístění odkazů, přičemž peníze jsou bezpečně uschovány, dokud nejsou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tímto živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště na volné noze: prohlédněte si více než 10 000 hotových služeb od textařů, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je podat nabídku.','Media Offload'=>'Odlehčení médií','Connection'=>'Připojení','What gets moved'=>'Co se přesouvá','How media is served'=>'Způsob poskytování médií','Move a batch now'=>'Přesunout dávku nyní','Media already moved is never affected by a change here — its address does not change.'=>'Již přesunutých médií se zdejší změna nijak nedotkne — jejich adresa se nezmění.','New uploads'=>'Nová nahrání','Move new uploads to Zinn® storage as they arrive'=>'Přesunout nová nahrávání do úložiště Zinn®, jakmile dorazí','Existing media'=>'Stávající média','Keep moving the media library that is already here'=>'Pokračujte v přesouvání knihovny médií, která se zde již nachází','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'Několik souborů za hodinu, na pozadí, se zahájením tam, kde proces skončil. Vypnutím této možnosti se proces pozastaví; nic z toho, co již bylo přesunuto, se nevrátí zpět.','Files per hourly pass'=>'Souborů na hodinový průchod','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'Každá příloha se skládá z několika souborů a každý z nich představuje kompletní nahrání. Na rychlém hostingu s velkorysým limitem provádění tuto hodnotu zvyšte; snižte ji, pokud se průchody předčasně přerušují.','Leave files smaller than'=>'Ponechat soubory menší než','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'Kilobajty. Malá ikona stojí na dodatečném připojení více, než kolik ušetří na disku, takže je málokdy důvod ji přesouvat. Nastavte na 0, pokud chcete přesunout vše.','Never move these types'=>'Nikdy tyto typy nepřesouvejte','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'Užitečné, když plugin čte soubor přímo z disku — písmo, PDF orazítkované nástrojem pro tvorbu formulářů, zvukový soubor, ve kterém přehrávač vyhledává.','These two are the ones to be careful with — read each description before changing it.'=>'U těchto dvou buďte opatrní — před provedením změny si přečtěte každý popis.','Serve from Zinn® storage'=>'Poskytovat z úložiště Zinn®','Point image and file addresses at Zinn® storage'=>'Nasměrujte adresy obrázků a souborů na úložiště Zinn®','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'Při vypnutí se soubory nahrají, ale stále se poskytují z tohoto serveru — což je bezpečný stav, zatímco kontrolujete, zda vše dorazilo. Při zapnutí se návštěvníkům obsah poskytuje z úložiště a tento server přestane přenášet provoz.','Free the disk space'=>'Uvolněte místo na disku','Delete the local copy once every size has uploaded'=>'Po nahrání všech velikostí smažte místní kopii','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'V tom spočívá smysl odlehčení a je to také ta nevratná část. Nechte to vypnuté, dokud nebude zapnuta možnost „Poskytovat z úložiště Zinn®“ a nezkontrolujete svůj web — lokální kopie je to jediné, co vás zachrání, pokud se na něco zapomnělo.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'Smazání místních kopií nelze z této obrazovky vrátit zpět. Nejprve si vytvořte zálohu — plugin Zinn® Connector to může udělat za vás.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'Tento web ještě není připojen k úložišti Zinn®, takže média není kam přesunout.','%d attachment moved.'=>'%d příloha byla přesunuta.' . "\0" . 'Bylo přesunuto %d příloh.' . "\0" . 'Bylo přesunuto %d příloh.' . "\0" . 'Bylo přesunuto %d příloh.','This site is not connected to Zinn® storage.'=>'Tento web není připojen k úložišti Zinn®.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'Vše je v pořádku — pouze ještě nedošlo ke spárování. Média zůstanou na tomto serveru, dokud k němu nedojde.','Connected, but the last upload failed.'=>'Připojeno, ale poslední nahrávání se nezdařilo.','Try a batch now'=>'Vyzkoušejte dávku nyní','Connected. Every attachment has been moved.'=>'Připojeno. Každá příloha byla přesunuta.','Connected. %1$s of %2$s attachments still on this server.'=>'Připojeno. %1$s z %2$s příloh stále zůstává na tomto serveru.','Moved so far'=>'Doposud přesunuto','%1$s files, %2$s'=>'%1$s souborů, %2$s','Still on this server'=>'Stále na tomto serveru','%1$s of %2$s attachments'=>'%1$s z %2$s příloh','Served from'=>'Načítáno z','this server'=>'tento server','Connect this site'=>'Připojit tento web','Open your Zinn Digital® dashboard, choose this site, open Files & databases, and press “Get a pairing code” under Images & video CDN. Paste the code below.'=>'Otevřete svou nástěnku Zinn Digital®, vyberte tento web, otevřete Soubory a databáze a pod položkou CDN pro obrázky a video stiskněte „Získat párovací kód“. Níže vložte kód.','Pairing code'=>'Párovací kód','Disconnect this site'=>'Odpojit tento web','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Nová nahraná média zůstanou na tomto serveru. Již přesunutá média budou nadále fungovat — jejich adresa se nemění.','You do not have permission to manage this site.'=>'Nemáte oprávnění spravovat tento web.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Vložte párovací kód z vaší nástěnky Zinn Digital®.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Připojeno. Nově nahrané soubory se budou od nynějška ukládat do Zinn Digital® a Vaše stávající média se přesunou na pozadí.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Odpojeno. Již přesunutá média nadále fungují; nová nahraná média zůstávají na tomto serveru.','That file could not be read from this server, so nothing was uploaded.'=>'Tento soubor se ze serveru nepodařilo přečíst, proto nebylo nic nahráno.','This site could not stream the upload, so nothing was sent.'=>'Tento web nemohl streamovat nahrávání, proto nebylo nic odesláno.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Tento soubor má velikost %1$s a PHP tohoto webu nepodporuje cURL, takže maximální velikost, kterou lze nahrát, je %2$s.','The upload could not be completed.'=>'Nahrávání se nepodařilo dokončit.','Storage refused the upload (HTTP %d).'=>'Úložiště odmítlo nahrávání (HTTP %d).','Style preset'=>'Předvolba stylu','A starting point. Anything below overrides it.'=>'Výchozí bod. Vše níže jej přepíše.','Use my own colours and sizes'=>'Použijte mé vlastní barvy a velikosti','Leave this off and the preset is used exactly as it is.'=>'Ponechte toto vypnuté a předvolba se použije přesně tak, jak je.','See the Zinn Digital® release notes.'=>'Zobrazit poznámky k vydání Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Aktualizační služba Zinn® nevydala odkaz ke stažení této aktualizace. Zkontrolujte, zda se tento web může připojit k platformě Zinn®, a poté to zkuste znovu.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Aktualizaci se nepodařilo stáhnout ze služby aktualizací Zinn® (%s). Zkuste to znovu za několik minut.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.']];